import{_ as a,o as t,c as l,ae as o}from"./chunks/framework.DCJ5T8RY.js";const m=JSON.parse('{"title":"一个关于babel的愚蠢错误","description":"","frontmatter":{"title":"一个关于babel的愚蠢错误","date":"2019-09-19"},"headers":[],"relativePath":"2019/silly-babel-mistake.md","filePath":"2019/silly-babel-mistake.md","lastUpdated":1786185344000}'),r={name:"2019/silly-babel-mistake.md"};function s(i,e,n,p,b,d){return t(),l("div",null,[...e[0]||(e[0]=[o('<blockquote><h4 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h4><p>babel不会打包node_modules里的文件，所以引入组件时，必须用组件打包后的代码</p></blockquote><h4 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-label="Permalink to &quot;问题描述&quot;">​</a></h4><p>npm install安装了公司内部组件之后，使用时import了源文件，然后项目打包报错:</p><blockquote><p><code>... UglifyJS unexpected token: punc &lt;&lt;(&gt;&gt; ....</code></p></blockquote><p>开始一直觉得奇怪，google一下是UglifyJS不认识ES6的代码，ES6肯定是babel处理的，自然问题出在babel上。 然后捣鼓了快半个小时，又是配.babelrc，又是安装各种babel-plugin。徒劳无功。</p><p>之后鼓起勇气，问了大佬，大佬一句话点醒梦中人： <strong>为了加速打包，babel不会转译node_modules里的文件</strong></p><p>然后就没有然后了....</p><p><strong>babel不转译，那么源文件里的ES6语法就不会被转为ES5，而UglifyJS不认识ES6语法，所以打包报错...</strong></p><h4 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h4><p>API dummy没有未来，自己还是太菜了，没有真正理解打包这个过程的真实含义，也没有理解很多webpack配置的背景。只是记住了怎么使用而已。一旦出现死记硬背场景之外的问题，就抓瞎了。</p><p>当然，公司组件没有按照commonJS弄个index.js入口文件以方便引入还是很坑的，吐槽结束。</p><p>技术进阶之路漫漫，我还要继续努力。</p>',12)])])}const _=a(r,[["render",s]]);export{m as __pageData,_ as default};
